const { google } = require('googleapis');
const fs = require('fs');
const path = require('path');

async function checkCalendar() {
  // Load calendar credentials and tokens
  const credentials = JSON.parse(fs.readFileSync('/root/auth/calendar/credentials.json', 'utf8'));
  const tokenData = JSON.parse(fs.readFileSync('/root/auth/calendar/tokens.json', 'utf8'));

  const tokens = tokenData.accounts ? tokenData.accounts[tokenData.defaultAccount] : tokenData;
  const { client_id, client_secret } = credentials.installed || credentials.web;

  const oauth2Client = new google.auth.OAuth2(client_id, client_secret);
  oauth2Client.setCredentials(tokens);

  const calendar = google.calendar({ version: 'v3', auth: oauth2Client });

  // Check January 6-9, 2026
  const timeMin = '2026-01-06T00:00:00-08:00';
  const timeMax = '2026-01-09T23:59:59-08:00';

  try {
    const res = await calendar.events.list({
      calendarId: 'primary',
      timeMin: timeMin,
      timeMax: timeMax,
      singleEvents: true,
      orderBy: 'startTime',
    });

    const events = res.data.items || [];
    if (events.length === 0) {
      console.log(JSON.stringify({ events: [], message: 'No events found for Jan 6-9, 2026' }));
    } else {
      const formatted = events.map(event => ({
        summary: event.summary,
        start: event.start.dateTime || event.start.date,
        end: event.end.dateTime || event.end.date,
      }));
      console.log(JSON.stringify({ events: formatted }, null, 2));
    }
  } catch (error) {
    console.error(JSON.stringify({ error: error.message }));
    process.exit(1);
  }
}

checkCalendar();

