# Let me try yet another approach. Create an OAuth client in the skillsbench project
# using the ADC credentials, then do the OAuth flow
cd ~/.claude/skills/gmail-skill && node -e "
const { google } = require('googleapis');
const fs = require('fs');

async function createOAuthClient() {
  const adc = JSON.parse(fs.readFileSync('/root/.config/gcloud/application_default_credentials.json', 'utf8'));
  const oauth2Client = new google.auth.OAuth2(adc.client_id, adc.client_secret);
  oauth2Client.setCredentials({ refresh_token: adc.refresh_token });
  const { credentials } = await oauth2Client.refreshAccessToken();

  // Check existing OAuth clients
  const res = await fetch(
    'https://oauth2.googleapis.com/token',
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        grant_type: 'refresh_token',
        client_id: adc.client_id,
        client_secret: adc.client_secret,
        refresh_token: adc.refresh_token,
        scope: 'https://www.googleapis.com/auth/calendar https://www.googleapis.com/auth/gmail.modify https://www.googleapis.com/auth/gmail.send'
      })
    }
  );
  const data = await res.json();
  console.log('Token response scope:', data.scope);

  // Check token info
  if (data.access_token) {
    const infoRes = await fetch('https://www.googleapis.com/oauth2/v1/tokeninfo?access_token=' + data.access_token);
    const info = await infoRes.json();
    console.log('Actual scopes:', info.scope);
  }
}

createOAuthClient().catch(e => console.error(e.message));
